sys_script_include.script:
var PatientUtilsClient = Class.create();
PatientUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	fetchPatientDetails: function () {
		var userId = this.getParameter('sysparm_user_id');
		var userTab = new GlideRecord('sys_user');
		result = {};
		if (userTab.get(userId)) {
			result.first_name = userTab.getValue('first_name');
			result.last_name = userTab.getValue('last_name');
			result.email = userTab.getValue('email');
			result.mobile = userTab.getValue('mobile_phone');
		}

		return JSON.stringify(result);
	},

	fetchPatientDetailsByPatientID: function (number) {
		var patientId = number || this.getParameter('sysparm_patient_id');
		var patientGr = new GlideRecord('u_patient_record');
		if (patientGr.get(patientId)) {
			var results = {
				pat_first_name: patientGr.getValue('u_first_name'),
				pat_last_name: patientGr.getValue('u_last_name'),
				pat_email: patientGr.getValue('email'),
				pat_vip: patientGr.getValue('u_vip'),
			};
			return JSON.stringify(results);
		}
	},

	checkIfVip: function () {
		var patientId = this.getParameter('sysparm_patient_id');
		var patientGr = new GlideRecord('u_patient_record');
		patientGr.get(patientId);
		if (patientGr.u_vip == true) {
			return JSON.stringify({ result: 'VIP' });
		}
		return JSON.stringify({ result: 'Non-VIP' });


	},


	type: 'PatientUtilsClient'
});
